    (function() {
      var sidebar = document.getElementById('final-desktop-sidebar');
      var toggle = document.getElementById('hiweb-chrome-toggle');
      if (!sidebar || !toggle) return;

      function setExpanded(expanded) {
        sidebar.classList.toggle('is-expanded', expanded);
        sidebar.classList.toggle('is-collapsed', !expanded);
        toggle.setAttribute('aria-label', expanded ? 'Ẩn chức năng' : 'Hiện chức năng');
      }

      if (toggle.dataset.cineloveBound !== '1') {
        toggle.dataset.cineloveBound = '1';
        toggle.addEventListener('click', function(event) {
          event.preventDefault();
          event.stopPropagation();
          setExpanded(!sidebar.classList.contains('is-expanded'));
        });
      }

      setExpanded(sidebar.getAttribute('data-default-expanded') === 'true');
    })();
